def main():
    input = stdin.read
    data = input().split()

    n = int(data[0])
    s = int(data[1])

    lands = [(int(data[i*2+2]), int(data[i*2+3])) for i in range(n)]

    if n == 0:
        stdout.write("0 0\n")
        return

    min_time = 24 * 60 + 1

    for i in range(n):
        if i == 0:
            if lands[i][0] > s:
                min_time = min(min_time, lands[i][0] - s)
        elif i == n-1:
            if 60 * lands[i][0] + lands[i][1] < 24 * 60 - s:
                min_time = min(min_time, 24 * 60 - s - (60 * lands[i][0] + lands[i][1]))
        else:
            gap = 60 * lands[i][0] + lands[i][1] - (60 * lands[i-1][0] + lands[i-1][1])
            if gap > s:
                min_time = min(min_time, gap // 2 + (60 * lands[i-1][0] + lands[i-1][1]) + s + 1)

    hour = min_time // 60
    minute = min_time % 60
    stdout.write(f"{hour} {minute}\n")

if __name__ == "__main__":
    main()
